mapper.select:
select date_format(task_date, '%Y-%m-%d') as day, count(1) as amount
from erp_day_task
where status = 'FAILED'
  and task_date >= #{start}
  and task_date <= #{end}
group by date_format(task_date, '%Y-%m-%d')

select status, count(1) as amount
from erp_day_task
where task_date >= #{start}
  and task_date <= #{end}
group by status
